/bin/zsh -c "python3 -c 'from fractions import Fraction
from math import gcd

def roots(cs,m):
    return sum(sum(c*a**i for i,c in enumerate(cs))%m==0 for a in range(m))
def mu(n):
    out=1
    p=2
    while p*p<=n:
        if n%p==0:
            n//=p
            out=-out
            if n%p==0:
                return 0
        p+=1
    return -out if n>1 else out

def cr(r,n):
    return sum(s*mu(r//s) for s in range(1,r+1) if r%s==0 and n%s==0)

def phi(r):
    return sum(gcd(a,r)==1 for a in range(1,r+1))

count=0
for cs in ([1,1],[2,0,1],[2,2],[4,0,4],[2,1,-2,1]):
    for p in (2,3,5,7):
        for h in range(1,2*p*p+1):
            beta={}
            for r in (p,p*p):
                beta[r]=sum((Fraction(cr(r,h*sum(c*a**i for i,c in enumerate(cs))),phi(r)) for a in range(r)),Fraction())/r
            j=2
            hh=h
            while j and hh%p==0:
                j-=1
                hh//=p
            delta=Fraction(roots(cs,p**j),p**j)
            actual=(1-Fraction(1,p*p))**2*(1+((p-1)*beta[p]+(p*p-p)*beta[p*p])/(p*p-1)**2)
            assert actual==1-Fraction(2,p*p)+delta/(p*p)
            count+=1
print(\"Verified\",count,\"exact local-factor identities, including nontrivial content and repeated roots.\")'"

